insert into public.tournaments (site_id,slug,slug_confirmed,name,format_code,format_params,currency_mode,game_scope,starts_at,ends_at,status,total_prize_sweeps,total_prize_gc,paid_places,rules_text,source_url,last_updated_on,seen_by,decision,decision_at) values ((select id from public.tournament_sites where slug = 'luckparty'), 'hit-the-multiplier-hit-it-category', true, 'Hit The Multiplier: Hit It Category', 'target_multiplier', '{"target_x": 9.1, "first_n": 5, "closest_n": 5, "closest_rule": "unstated (absolute distance vs from below)", "times_assumed": "start"}'::jsonb, 'SC', 'category:Hit It', (timestamp '2026-10-01 13:00' at time zone 'America/New_York'), (timestamp '2026-10-02 12:59' at time zone 'America/New_York'), 'live', 300, 3000000, 5, 'Play any game in the Hit It Category in SC mode. Be among the first 5 to hit the 9.1X multiplier, or 5 closest to it. Ends Oct 2 at 12:59 PM EDT.', 'https://luckparty.com/promotions/promo/hit-the-multiplier-hit-it-category', '2026-10-01', 'manual', '{"verdict": "incidental", "headline": "Cheap shot, ends 11:59 AM CT today: 200 min-bet SC spins on a Hit It line game also earn this week''s raffle SC ticket.", "target": {"metric": "spins", "value": 200, "note": "cap the session; stop on a 9.1x or when the 200 are done"}, "games": [{"name": "Luck Party Kong", "why": "line-pay slot (Jili): many small line combinations, so more ways to land near 9.1x - inferred, paytable not public"}, {"name": "Luck Party Blue Birds Bonanza", "why": "line-pay slot (Edge Labs) - same reasoning, also in Hot"}, {"name": "avoid: Luck Party Bonsai / Diamonds Hold & Win", "why": "coin-value Hold & Win payouts land in coarse steps; fewer paths to an exact 9.1x"}], "bet": "minimum SC bet (multiplier is bet-independent)", "cost_estimate_sweeps": 0.8, "cost_basis": "200 spins x 0.10 SC x 4% edge; double it if the min bet is 0.20", "bankroll_sweeps": 15, "time_estimate_min": 25, "ev_note": "Prize equity unknown: the first-5 slots were probably filled overnight, but ''closest to 9.1x'' stays open until the end. Treat it as a free roll on spins you take anyway for the raffle.", "confidence": "low", "data_gaps": ["min SC bet per Hit It game", "whether ''closest'' means absolute distance or from below", "how fast the first 5 hits happen (log the time you see it hit)"], "risk": "Negative EV on its own (~4% of what you spin). One account, no scripts; stop at the 200 spins.", "stack_with": ["Weekly Spin Raffle (200 SC spins = 1 ticket)"], "log_command": "Log tournament entry luckparty hit-the-multiplier-hit-it-category 2026-10-02: spins <n>, best multiplier <x>, closest to 9.1 <x>, games <names>"}'::jsonb, now())
